INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Profitcenter immer eine eigenständige Firma?', 2, '[{"text": "Nein", "correct": true, "because": "Teil eines Unternehmens"}, {"text": "Ja", "correct": false, "because": "Interne Einheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel eines Profitcenters?', 3, '[{"text": "Gewinnerzielung", "correct": true, "because": "Fokussiert auf Profitabilität"}, {"text": "Minimale Kosten", "correct": false, "because": "Gewinn im Vordergrund"}, {"text": "Manuelle Abrechnung", "correct": false, "because": "Automatisierung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein Profitcenter?', 5, '[{"text": "Eigene Erfolgsrechnung", "correct": true, "because": "Misst Gewinn"}, {"text": "Verantwortung für Ergebnisse", "correct": true, "because": "Manager steuern"}, {"text": "Unabhängige Rechtsform", "correct": false, "because": "Teil des Unternehmens"}, {"text": "Keine Kosten", "correct": false, "because": "Kosten werden kalkuliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Profitcenter haben Budgetverantwortung. b) Sie sind immer Costcenter.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) fokussiert nur Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einrichtung eines Profitcenters?', 4, '[{"text": "Umsatzziele", "correct": false, "because": "Bestimmen Erfolg"}, {"text": "Kostenverantwortung", "correct": false, "because": "Steuert Profit"}, {"text": "Bürogestaltung", "correct": true, "because": "Irrelevant für Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Profitcenter eigene Umsätze erzielen muss?', 2, '[{"text": "Ja", "correct": true, "because": "Umsatz ist Gewinngrundlage"}, {"text": "Nein", "correct": false, "because": "Erfolgsmessung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Profitcenter-Manager?', 3, '[{"text": "Ergebnisoptimierung", "correct": true, "because": "Maximiert Gewinn"}, {"text": "Nur Kosten senken", "correct": false, "because": "Umsatz ebenso wichtig"}, {"text": "Manuelle Abrechnung", "correct": false, "because": "Automatisiert besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kennzahlen sind für ein Profitcenter relevant?', 5, '[{"text": "Umsatz", "correct": true, "because": "Misst Einnahmen"}, {"text": "Gewinnmarge", "correct": true, "because": "Zeigt Rentabilität"}, {"text": "Mitarbeiteranzahl", "correct": false, "because": "Sekundär"}, {"text": "Bürofläche", "correct": false, "because": "Nicht erfolgsrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Profitcenter sind ergebnisverantwortlich. b) Sie haben keine Kosten. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) berücksichtigt Kosten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein Profitcenter?', 4, '[{"text": "Erfolgsmessung", "correct": false, "because": "Kern des Konzepts"}, {"text": "Umsatzverantwortung", "correct": false, "because": "Definiert Profit"}, {"text": "Grafische Animationen", "correct": true, "because": "Irrelevant für Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Profitcenter dasselbe wie ein Costcenter?', 2, '[{"text": "Nein", "correct": true, "because": "Costcenter fokussiert Kosten"}, {"text": "Ja", "correct": false, "because": "Profitcenter auf Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmensbereiche können Profitcenter sein?', 4, '[{"text": "Produktabteilung", "correct": true, "because": "Erzielt Umsatz"}, {"text": "Vertrieb", "correct": true, "because": "Verantwortlich für Gewinn"}, {"text": "Facility Management", "correct": false, "because": "Eher Costcenter"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Profitcenter unabhängig sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Teil des Unternehmens"}, {"text": "Ja", "correct": false, "because": "Autonom, aber eingebunden"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Profitcenter?', 3, '[{"text": "Gewinnziele", "correct": true, "because": "Definiert Erfolg"}, {"text": "Minimale Verantwortung", "correct": false, "because": "Verantwortung zentral"}, {"text": "Manuelle Abrechnung", "correct": false, "because": "Systeme effizienter"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Profitcenter messen Umsatz und Kosten. b) Sie sind nur für Produktion.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch für Dienstleistungen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Profitcenter?', 5, '[{"text": "Transparenz", "correct": true, "because": "Zeigt Ergebnisse"}, {"text": "Ergebnisverantwortung", "correct": true, "because": "Fördert Effizienz"}, {"text": "Keine Kosten", "correct": false, "because": "Kosten werden kalkuliert"}, {"text": "Unabhängige Rechtsform", "correct": false, "because": "Interne Einheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Profitcenter unwichtig?', 3, '[{"text": "Umsatzmessung", "correct": false, "because": "Bestimmt Gewinn"}, {"text": "Kostensteuerung", "correct": false, "because": "Sichert Profit"}, {"text": "Bildschirmauflösung", "correct": true, "because": "Kein Geschäftsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Profitcenter externe Kunden braucht?', 2, '[{"text": "Nein", "correct": true, "because": "Interne Leistungen möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Berichtet ein Profitcenter direkt an die Geschäftsleitung?', 3, '[{"text": "Ja", "correct": true, "because": "Ergebnisse werden überwacht"}, {"text": "Nein", "correct": false, "because": "Reporting üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu einem Profitcenter?', 4, '[{"text": "IT-Dienstleistungsabteilung mit Umsatzzielen", "correct": true, "because": "Gewinnerzielung intern"}, {"text": "Musikwiedergabe", "correct": false, "because": "Keine Geschäftseinheit"}, {"text": "Netzwerkwartung", "correct": false, "because": "Eher Costcenter"}]');
